import{_ as t,o as i,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-11-05（生物医学 · 让「核糖体移码」只在癌细胞里开闸）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-11-05-biomed.md","filePath":"topics/biomedicine/science-daily-2026-11-05-biomed.md"}'),e={name:"topics/biomedicine/science-daily-2026-11-05-biomed.md"};function r(c,o,g,d,a,l){return i(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-11-05-生物医学-·-让「核糖体移码」只在癌细胞里开闸" tabindex="-1">科学日报 · 2026-11-05（生物医学 · 让「核糖体移码」只在癌细胞里开闸） <a class="header-anchor" href="#科学日报-·-2026-11-05-生物医学-·-让「核糖体移码」只在癌细胞里开闸" aria-label="Permalink to &quot;科学日报 · 2026-11-05（生物医学 · 让「核糖体移码」只在癌细胞里开闸）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> — 第55期 ｜ 科学板块（生物医学向 1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-05-生物医学-·-1-1-把「翻译失调」当癌细胞的漏洞——密码子对特异性核糖体移码驱动的选择性基因线路" tabindex="-1">科学日报 2026-11-05（生物医学 · 1/1）：把「翻译失调」当癌细胞的漏洞——密码子对特异性核糖体移码驱动的选择性基因线路 <a class="header-anchor" href="#科学日报-2026-11-05-生物医学-·-1-1-把「翻译失调」当癌细胞的漏洞——密码子对特异性核糖体移码驱动的选择性基因线路" aria-label="Permalink to &quot;科学日报 2026-11-05（生物医学 · 1/1）：把「翻译失调」当癌细胞的漏洞——密码子对特异性核糖体移码驱动的选择性基因线路&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ DOI: 10.1038/s41586-026-11200-4 ｜ Nature (2026)</p></blockquote><ul><li>问题：<strong>核糖体移码（ribosomal frameshifting）</strong> 是少见的<strong>翻译重编码</strong>事件，最广为人知的是<strong>病毒基因表达</strong>中的调控作用，但其在<strong>哺乳动物中的生理意义</strong>长期不清——它能否被<strong>肿瘤特异性</strong>地利用，此前未知。</li><li>方法：在哺乳动物细胞/肿瘤模型中筛查触发 <strong>−1 移码</strong>的<strong>特定密码子对</strong>，解析其<strong>核糖体暂停</strong>机制（tRNA 与氨基酸可用性、核糖体质量控制 RQC、核糖体蛋白 S6 磷酸化），并据此<strong>工程化一条「移码激活的合成治疗线路（FAST）」</strong>，用 AAV9 在小鼠肿瘤模型中做系统递送。</li><li>结果（实测）： <ul><li><strong>特定密码子对只在癌细胞中高效触发 −1 移码</strong>；机制来自<strong>核糖体暂停</strong>（受 <strong>tRNA/氨基酸可用性</strong>影响），并被<strong>受损的 RQC</strong> 与 <strong>S6 持续磷酸化</strong>放大；</li><li>这种密码子对特异的移码是<strong>癌细胞普遍存在的翻译失调内禀状态</strong>，会<strong>重塑蛋白质合成</strong>；</li><li><strong>FAST 线路</strong>条件性表达<strong>焦亡效应分子 gasdermin D</strong>：在<strong>多种癌细胞中被激活、选择性诱发焦亡</strong>，<strong>正常组织无可检出毒性</strong>；</li><li><strong>AAV9 系统递送</strong>在<strong>结直肠癌、胰腺癌小鼠模型</strong>中引发<strong>显著肿瘤消退 + 强免疫激活</strong>，并与<strong>免疫检查点阻断协同</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code>）： <ol><li><strong>「把疾病的『内禀异常状态』当选择性开关，而不是设计外源开关」</strong>——癌细胞自带<strong>翻译失调</strong>（RQC 受损 + S6 磷酸化），作者没有造一个新的人造启动子，而是<strong>让治疗基因的激活条件正好是癌细胞的固有缺陷</strong>；判据：<strong>当要为『只杀靶细胞』找选择性时，先问靶细胞自己有哪些『内禀状态』可被当作触发器</strong>（呼应母题「<strong>改路径优于加力度</strong>」与「<strong>约束-涌现</strong>」）。</li><li><strong>「口头/表型的选择性 ≠ 真实选择性，用正常组织毒性收口」</strong>——FAST 的关键安全论证是<strong>正常组织无可检出毒性</strong>这一<strong>外部可观测后果</strong>，而非体外表型；判据：<strong>宣称选择性时，必须给出『非靶侧无可检出伤害』的端到端证据</strong>（呼应母题「<strong>外部信号 &gt; 自评分 / 否证性判据</strong>」）。</li><li><strong>与库内的呼应</strong>：与 <code>topics/biomedicine/science-daily-2026-11-02-biomed.md</code>（METTL13 提升促癌蛋白合成、同义改写可逆转）同族——<strong>翻译层面的调控（移码 / 密码子偏好 / 修饰）是肿瘤可劫持、也可攻击的对称面</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第55期 科学板块</p></blockquote><p>关键词：科学日报第55期、核糖体移码ribosomal frameshifting、翻译重编码translational recoding、−1移码、特定密码子对codon pair、癌细胞选择性、核糖体暂停ribosomal pausing、tRNA与氨基酸可用性、核糖体质量控制RQC受损、核糖体蛋白S6持续磷酸化、翻译失调内禀状态、重塑蛋白合成、FAST移码激活合成治疗线路、gasdermin D、焦亡pyroptosis、正常组织无可检出毒性、AAV9系统递送、结直肠癌胰腺癌小鼠模型、肿瘤消退、免疫激活、免疫检查点阻断协同、把内禀异常状态当选择性开关、外部信号大于自评分、否证性判据优于肯定性判据、改路径优于加力度、约束涌现</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-11-04-biomed.md</code>、<code>topics/biomedicine/science-daily-2026-11-02-biomed.md</code>、<code>ScienceDaily/daily/2026-11-05.md</code></p>',10)])])}const b=t(e,[["render",r]]);export{p as __pageData,b as default};
